test("błąd tytułu opisuje pole i przenosi fokus bez zapisu",async()=>{const user=userEvent.setup(),onCreate=vi.fn<(values:FormValues)=>Promise<void>>().mockResolvedValue();render(<NewTicketForm onCreate={onCreate}/>);await user.type(screen.getByLabelText("Tytuł")," abc ");await user.click(screen.getByRole("button",{name:"Utwórz"}));expect(onCreate).not.toHaveBeenCalled();expect(screen.getByLabelText("Tytuł")).toHaveAttribute("aria-invalid","true");expect(screen.getByLabelText("Tytuł")).toHaveAccessibleDescription(/co najmniej 5 znaków/);expect(screen.getByLabelText("Tytuł")).toHaveFocus();});test("poprawne dane są przycięte i resetowane po sukcesie",async()=>{const user=userEvent.setup(),onCreate=vi.fn<(values:FormValues)=>Promise<void>>().mockResolvedValue();render(<NewTicketForm onCreate={onCreate}/>);await user.type(screen.getByLabelText("Tytuł"),"  Błąd eksportu CSV  ");await user.type(screen.getByLabelText("Opis"),"  opis  ");await user.selectOptions(screen.getByLabelText("Priorytet"),"HIGH");await user.click(screen.getByRole("button",{name:"Utwórz"}));expect(onCreate).toHaveBeenCalledExactlyOnceWith({title:"Błąd eksportu CSV",description:"opis",priority:"HIGH"});await waitFor(()=>expect(screen.getByLabelText("Tytuł")).toHaveValue(""));expect(screen.getByLabelText("Opis")).toHaveValue("");expect(screen.getByLabelText("Priorytet")).toHaveValue("NORMAL");});test("CRITICAL wymaga opisu i fokusuje właściwe pole",async()=>{const user=userEvent.setup(),onCreate=vi.fn<(values:FormValues)=>Promise<void>>().mockResolvedValue();render(<NewTicketForm onCreate={onCreate}/>);await user.type(screen.getByLabelText("Tytuł"),"Awaria eksportu");await user.selectOptions(screen.getByLabelText("Priorytet"),"CRITICAL");await user.click(screen.getByRole("button",{name:"Utwórz"}));expect(onCreate).not.toHaveBeenCalled();expect(screen.getByLabelText("Opis")).toHaveFocus();expect(screen.getByLabelText("Opis")).toHaveAccessibleDescription(/co najmniej 10 znaków/);await user.type(screen.getByLabelText("Opis"),"Długi opis awarii");await user.click(screen.getByRole("button",{name:"Utwórz"}));expect(onCreate).toHaveBeenCalledExactlyOnceWith({title:"Awaria eksportu",description:"Długi opis awarii",priority:"CRITICAL"});});test("błąd zapisu nie usuwa szkicu, a poprawka pozwala ponowić",async()=>{const user=userEvent.setup(),onCreate=vi.fn<(values:FormValues)=>Promise<void>>().mockRejectedValueOnce(Error("sieć")).mockResolvedValue();render(<NewTicketForm onCreate={onCreate}/>);await user.type(screen.getByLabelText("Tytuł"),"Błąd eksportu");await user.click(screen.getByRole("button",{name:"Utwórz"}));expect(await screen.findByRole("alert")).toHaveTextContent("Dane pozostają");expect(screen.getByLabelText("Tytuł")).toHaveValue("Błąd eksportu");await user.clear(screen.getByLabelText("Tytuł"));await user.type(screen.getByLabelText("Tytuł"),"Naprawiony eksport");await user.click(screen.getByRole("button",{name:"Utwórz"}));expect(onCreate).toHaveBeenCalledTimes(2);await waitFor(()=>expect(screen.getByLabelText("Tytuł")).toHaveValue(""));});test("nierozstrzygnięty zapis blokuje drugi klik",async()=>{const user=userEvent.setup();let finish!:()=>void;const onCreate=vi.fn<(values:FormValues)=>Promise<void>>(()=>new Promise<void>(resolve=>{finish=resolve;}));render(<NewTicketForm onCreate={onCreate}/>);await user.type(screen.getByLabelText("Tytuł"),"Awaria eksportu");await user.click(screen.getByRole("button",{name:"Utwórz"}));expect(screen.getByRole("button",{name:"Tworzenie…"})).toBeDisabled();await user.click(screen.getByRole("button",{name:"Tworzenie…"}));expect(onCreate).toHaveBeenCalledTimes(1);finish();await waitFor(()=>expect(screen.getByRole("button",{name:"Utwórz"})).toBeEnabled());});

