afterEach(()=>{cleanup();vi.clearAllTimers();vi.useRealTimers();});test("cofnięcie przywraca wiersz bez mutacji po czasie",async()=>{vi.useFakeTimers();const onDelete=vi.fn().mockResolvedValue(undefined);render(<TicketListWithUndo onDeleteOnServer={onDelete}/>);fireEvent.click(screen.getByRole("button",{name:"Usuń API timeout"}));expect(screen.queryByText("API timeout")).not.toBeInTheDocument();fireEvent.click(screen.getByRole("button",{name:"Cofnij"}));expect(screen.getByText("API timeout")).toBeVisible();await act(async()=>{await vi.advanceTimersByTimeAsync(6000);});expect(onDelete).not.toHaveBeenCalled();});test("brak cofnięcia wywołuje zapis dopiero na granicy 5 sekund",async()=>{vi.useFakeTimers();const onDelete=vi.fn().mockResolvedValue(undefined);render(<TicketListWithUndo onDeleteOnServer={onDelete}/>);fireEvent.click(screen.getByRole("button",{name:"Usuń API timeout"}));await act(async()=>{await vi.advanceTimersByTimeAsync(4999);});expect(onDelete).not.toHaveBeenCalled();await act(async()=>{await vi.advanceTimersByTimeAsync(1);});expect(onDelete).toHaveBeenCalledExactlyOnceWith(42);expect(screen.queryByRole("button",{name:"Cofnij"})).not.toBeInTheDocument();});test("błąd zapisu przywraca rekord i pokazuje alert",async()=>{vi.useFakeTimers();render(<TicketListWithUndo onDeleteOnServer={vi.fn().mockRejectedValue(Error("sieć"))}/>);fireEvent.click(screen.getByRole("button",{name:"Usuń API timeout"}));await act(async()=>{await vi.advanceTimersByTimeAsync(5000);});expect(screen.getByRole("alert")).toHaveTextContent("Nie udało się usunąć");expect(screen.getByText("API timeout")).toBeVisible();});test("unmount anuluje oczekującą mutację, nie udaje rollbacku rozpoczętego zapisu",async()=>{vi.useFakeTimers();const onDelete=vi.fn().mockResolvedValue(undefined);const view=render(<TicketListWithUndo onDeleteOnServer={onDelete}/>);fireEvent.click(screen.getByRole("button",{name:"Usuń API timeout"}));view.unmount();await act(async()=>{await vi.advanceTimersByTimeAsync(6000);});expect(onDelete).not.toHaveBeenCalled();});test("debounce filtruje dopiero po przerwie",async()=>{vi.useFakeTimers();render(<DebouncedSearch/>);fireEvent.change(screen.getByRole("searchbox",{name:"Szukaj lokalnie"}),{target:{value:"API"}});expect(screen.getByRole("status")).toHaveTextContent("Wyników: 3");await act(async()=>{await vi.advanceTimersByTimeAsync(299);});expect(screen.getByText("Dokumentacja")).toBeVisible();await act(async()=>{await vi.advanceTimersByTimeAsync(1);});expect(screen.getByRole("status")).toHaveTextContent("Wyników: 2");expect(screen.queryByText("Dokumentacja")).not.toBeInTheDocument();});

